<section class="panel" id="colegiaturas"><h2>2. Colegiaturas por nivel y grado</h2><div class="note">Una configuración determina el monto, los meses de cobro y el vencimiento. Las obligaciones ya emitidas no se modifican automáticamente.</div><form method="POST" action="{{ route('direccion.finanzas.configuracion.colegiaturas.store') }}">@csrf<input type="hidden" name="ciclo_escolar_id" value="{{ $cicloId }}"><div class="grid"><div><label>Concepto de colegiatura</label><select name="concepto_cobro_id" required><option value="">Seleccionar</option>@foreach($conceptos->where('tipo','COLEGIATURA')->where('activo',true) as $c)<option value="{{ $c->id }}">{{ $c->nombre }}</option>@endforeach</select></div><div><label>Nivel</label><select name="nivel_id" id="nivel_config" required><option value="">Seleccionar</option>@foreach($niveles as $n)<option value="{{ $n->id }}">{{ $n->nombre }}</option>@endforeach</select></div><div><label>Grado (opcional: todos los del nivel)</label><select name="grado_id" id="grado_config"><option value="">Todos los grados del nivel</option>@foreach($grados as $g)<option value="{{ $g->id }}" data-nivel="{{ $g->nivel_id }}">{{ $g->nombre }}</option>@endforeach</select></div><div><label>Monto (Q)</label><input type="number" name="monto" min="0" step="0.01" required></div><div><label>Día de vencimiento</label><input type="number" name="dia_vencimiento" min="1" max="31" placeholder="Ej. 10"></div><div><label>Vigente desde</label><input type="date" name="vigente_desde"></div><div><label>Vigente hasta</label><input type="date" name="vigente_hasta"></div></div><p class="muted" style="margin-top:15px">Meses en que se genera el cobro (dejar sin seleccionar para una configuración sin meses definidos).</p><div class="months">@foreach([1=>'Ene',2=>'Feb',3=>'Mar',4=>'Abr',5=>'May',6=>'Jun',7=>'Jul',8=>'Ago',9=>'Sep',10=>'Oct',11=>'Nov',12=>'Dic'] as $mes=>$nombre)<label><input type="checkbox" name="meses_cobro[]" value="{{ $mes }}">{{ $nombre }}</label>@endforeach</div><div class="actions"><button class="btn">Guardar colegiatura</button></div></form><div class="table-wrap"><table><thead><tr><th>Concepto</th><th>Nivel / grado</th><th>Monto</th><th>Vencimiento</th><th>Meses</th><th>Vigencia</th></tr></thead><tbody>@forelse($colegiaturas as $c)<tr><td>{{ $c->concepto_cobro?->nombre }}</td><td>{{ $c->nivel?->nombre }} / {{ $c->grado?->nombre ?? 'Todos' }}</td><td>Q {{ number_format($c->monto,2) }}</td><td>Día {{ $c->dia_vencimiento ?? '—' }}</td><td>{{ implode(', ', $c->meses_cobro ?? []) ?: 'Sin definir' }}</td><td>{{ $c->vigente_desde?->format('d/m/Y') ?? '—' }} – {{ $c->vigente_hasta?->format('d/m/Y') ?? '—' }}</td></tr>@empty<tr><td colspan="6">No hay colegiaturas configuradas para este ciclo.</td></tr>@endforelse</tbody></table></div></section>
<section class="panel" id="mora"><h2>3. Configuración de mora</h2><div class="note">La mora se configura por concepto y ciclo escolar. Los días de gracia se cuentan después del vencimiento. Guardar una regla no aplica recargos retroactivos ni modifica pagos.</div><form method="POST" action="{{ route('direccion.finanzas.configuracion.mora.store') }}">@csrf<input type="hidden" name="ciclo_escolar_id" value="{{ $cicloId }}"><div class="grid"><div><label>Concepto sujeto a mora</label><select name="concepto_cobro_id" required><option value="">Seleccionar</option>@foreach($conceptos->where('activo',true) as $c)<option value="{{ $c->id }}">{{ $c->nombre }}</option>@endforeach</select></div><div><label>Tipo de recargo</label><select name="tipo" required><option value="FIJO">Monto fijo (Q)</option><option value="PORCENTAJE">Porcentaje (%)</option></select></div><div><label>Valor</label><input type="number" name="valor" step="0.01" min="0" required placeholder="Ej. 25.00"></div><div><label>Días de gracia</label><input type="number" name="dias_gracia" min="0" max="65535" value="0" required></div><div><label>Periodicidad</label><select name="periodicidad" required><option value="UNICA">Una sola vez</option><option value="DIARIA">Diaria</option><option value="MENSUAL">Mensual</option></select></div><div><label>Vigente desde</label><input type="date" name="vigente_desde" required></div><div><label>Vigente hasta (opcional)</label><input type="date" name="vigente_hasta"></div></div><div class="actions"><button class="btn">Autorizar regla de mora</button></div></form><div class="table-wrap"><table><thead><tr><th>Concepto</th><th>Tipo</th><th>Valor</th><th>Gracia</th><th>Periodicidad</th><th>Vigencia</th></tr></thead><tbody>@forelse($moras as $m)<tr><td>{{ $m->concepto_cobro?->nombre }}</td><td>{{ $m->tipo }}</td><td>{{ $m->tipo === 'FIJO' ? 'Q ' : '' }}{{ number_format($m->valor,2) }}{{ $m->tipo === 'PORCENTAJE' ? '%' : '' }}</td><td>{{ $m->dias_gracia }} días</td><td><span class="tag">{{ $m->periodicidad }}</span></td><td>{{ $m->vigente_desde?->format('d/m/Y') }} – {{ $m->vigente_hasta?->format('d/m/Y') ?? 'Sin fin definido' }}</td></tr>@empty<tr><td colspan="6">No hay reglas de mora configuradas para este ciclo.</td></tr>@endforelse</tbody></table></div></section>
