<script>
document.addEventListener('DOMContentLoaded', function () {
 const nivel = document.getElementById('nivel_config'); const grado = document.getElementById('grado_config');
 if (!nivel || !grado) return;
 function filtrar() { [...grado.options].forEach(o => {if (!o.value) return; o.hidden = o.dataset.nivel !== nivel.value; o.disabled = o.hidden;}); if (grado.selectedOptions[0]?.disabled) grado.value = ''; }
 nivel.addEventListener('change', filtrar); filtrar();
});
</script>
